const l = $json;
const consent = l.consent_followup === true || String(l.consent_followup).toLowerCase() === 'true';
const crates = Number((String(l.size_estimate || '').match(/\d+/) || [0])[0]);
const big = /hotel|restaurant|caterer|weekly/i.test(l.wants || '') && crates >= 10;
return { platform: l.platform, handle_or_thread_id: l.handle_or_thread_id, source_link: l.source_link || '',
  wants: String(l.wants || '').slice(0, 300), size_estimate: l.size_estimate || 'unknown', consent_followup: consent, big };
